SELECT MAX(icustays.los) AS max_length_of_stay FROM patients JOIN icustays ON patients.subject_id = icustays.subject_id WHERE patients.gender = 'F' AND patients.anchor_year = 72 AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2015 AND 2018 AND (icustays.los <= 720 OR icustays.los IS NULL) AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = patients.subject_id AND diagnoses_icd.icd_code IN ('E116', 'E117', 'E118', 'E119'));